// Accepts every shape a buyer's agent plausibly sends.
//
// The previous version took two: a packages array, or a dependencies block. An
// agent told "check lodash 4.17.20" sends neither -- it sends the package and
// the version at the top level, because that is the obvious encoding of the
// sentence. It then threw, the throw became a 500, and the buyer was told the
// worker was down. The worker was not down; it was refusing a reasonable
// request for a reason nobody could see.
//
// A paid worker is a public API with no docs and no support channel. Being
// liberal about the input is not sloppiness here, it is the job.

const body = $input.first().json.body || {};
const input = body.input ?? body ?? {};

const eco = (e) => String(e || input.ecosystem || 'npm');
const clean = (v) => String(v).replace(/^[\^~>=<\s]+/, '').trim();

let pkgs = [];
let shape = '';

if (Array.isArray(input.packages)) {
  shape = 'packages[]';
  pkgs = input.packages.map((p) => ({ name: p.name, version: p.version, ecosystem: eco(p.ecosystem) }));
} else if (Array.isArray(input)) {
  shape = 'array';
  pkgs = input.map((p) => ({ name: p.name, version: p.version, ecosystem: eco(p.ecosystem) }));
} else if (input.dependencies && typeof input.dependencies === 'object') {
  shape = 'dependencies{}';
  pkgs = Object.entries(input.dependencies).map(([name, range]) => ({
    name, version: clean(range), ecosystem: eco(),
  }));
} else if (input.name && input.version) {
  shape = 'name+version';
  pkgs = [{ name: input.name, version: clean(input.version), ecosystem: eco(input.ecosystem) }];
} else if (input.package && input.version) {
  shape = 'package+version';
  pkgs = [{ name: input.package, version: clean(input.version), ecosystem: eco(input.ecosystem) }];
} else if (typeof input === 'string') {
  // "lodash 4.17.20" or "lodash@4.17.20".
  shape = 'string';
  const m = input.trim().match(/^([@\w\/.-]+?)[@\s]+v?([\d][\w.+-]*)$/);
  if (m) pkgs = [{ name: m[1], version: m[2], ecosystem: eco() }];
}

pkgs = pkgs
  .filter((p) => p && p.name && p.version)
  .map((p) => ({ name: String(p.name), version: clean(p.version), ecosystem: eco(p.ecosystem) }))
  .slice(0, 100);

if (!pkgs.length) {
  // The error carries what was actually received. A worker that says only
  // "bad input" makes its buyer guess, and its buyer is a language model that
  // will guess differently every time.
  throw new Error(
    'No package/version pairs found in the request. Send one of: ' +
    '{"input":{"name":"lodash","version":"4.17.20"}}, ' +
    '{"input":{"packages":[{"name","version","ecosystem"}]}}, or ' +
    '{"input":{"dependencies":{"lodash":"4.17.20"}}}. ' +
    'Received: ' + JSON.stringify(input).slice(0, 200)
  );
}

return [{ json: {
  pkgs,
  shape,
  queries: pkgs.map((p) => ({
    package: { name: p.name, ecosystem: p.ecosystem },
    version: String(p.version),
  })),
} }];

const item = $input.first().json;
const raw = item.data ?? item;

let osv;
try {
  osv = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error('OSV did not return JSON: ' + String(raw).slice(0, 300));
}

const pkgs = $('Build queries').first().json.pkgs;

// A scanner that cannot tell "found nothing" from "the lookup never ran" is
// worse than no scanner at all, because it sells a clean bill of health for a
// question it failed to ask. OSV answers querybatch with exactly one result per
// query, in order. Anything else means we do not know, and the only honest move
// is to fail loudly rather than return zero findings that look identical to a
// real all-clear.
const results = osv && osv.results;
if (!Array.isArray(results) || results.length !== pkgs.length) {
  throw new Error(
    'OSV returned ' + (Array.isArray(results) ? results.length : 'no') +
    ' result(s) for ' + pkgs.length + ' query/queries. Refusing to report a clean scan. ' +
    'Sent: ' + JSON.stringify($('Build queries').first().json.queries).slice(0, 200) +
    ' Got: ' + JSON.stringify(osv).slice(0, 300)
  );
}

const findings = [];
pkgs.forEach((p, i) => {
  const vulns = (results[i] && results[i].vulns) || [];
  if (vulns.length) {
    findings.push({
      package: p.name,
      version: p.version,
      advisories: vulns.map((v) => ({ id: v.id, url: 'https://osv.dev/vulnerability/' + v.id })),
    });
  }
});

// `scanned` and `checkedAt` are part of the product, not decoration: what is
// being bought is a dated statement about a specific set of versions.
return [{ json: { output: {
  scanned: pkgs.length,
  vulnerable: findings.length,
  findings,
  source: 'osv.dev',
  checkedAt: new Date().toISOString(),
} } }];
